import {expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

// Spec: specs/hal-engine-config-hooks/spec.md#7
it('reports a beforeSession Error with the original session and error', async () => {
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const failure = new Error('allocation failed');
  const errors: unknown[] = [];
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'You are HAL.'}),
    undefined,
    {
      hooks: {
        beforeSession: async () => {
          throw failure;
        },
        onError: async (failedSession, error) => {
          errors.push({sameSession: failedSession === session, sameError: error === failure});
        },
      },
    }
  );

  const rejection = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({errors, sameRejection: rejection === failure}).toEqual({
    errors: [{sameSession: true, sameError: true}],
    sameRejection: true,
  });
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/beforeSessionError.test.ts"
